// Validación en BD: misma fila reactivada, sin duplicar, fecha original intacta.
pm.sendRequest(utils.bodySqlRest(
  "SELECT id, activo, asignado_en FROM usuario_roles WHERE usuario_id = $1 AND role_id = $2",
  [Number(pm.collectionVariables.get("usuarioId")), Number(pm.collectionVariables.get("roleEditorId"))]
), (err, res) => {
  if (err) throw err;
  const rows = res.json().data;

  pm.test("La BD sigue teniendo una sola fila para el par usuario-rol", () => {
    pm.expect(rows).to.have.lengthOf(1);
  });
  pm.test("La BD confirma la reactivación: activo = true y mismo id", () => {
    pm.expect(rows[0].activo).to.eql(true);
    pm.expect(String(rows[0].id)).to.eql(pm.variables.get("asignacionIdAntes"));
  });
  pm.test("La BD conserva la fecha original asignado_en", () => {
    pm.expect(String(rows[0].asignado_en)).to.eql(pm.variables.get("asignadoEnAntes"));
  });
});

